import requests

BASE_URL = "https://api.socbench.example"

analytics_response = requests.post(
    f"{BASE_URL}/analytics/generate",
    json={"system": "supply chain", "report_type": "detailed"},
)
analytics_response.raise_for_status()
analytics = analytics_response.json()

components_response = requests.get(f"{BASE_URL}/components")
components_response.raise_for_status()
components = components_response.json()

# Select a component only when the analytics explicitly identifies it as no longer needed.
unneeded_ids = set()
if isinstance(analytics, dict):
    candidates = analytics.get("components_to_remove", [])
    for candidate in candidates:
        if isinstance(candidate, dict) and candidate.get("no_longer_needed") is True:
            if candidate.get("id") is not None:
                unneeded_ids.add(str(candidate["id"]))

if isinstance(components, dict):
    components = components.get("components", [])

for component in components:
    if not isinstance(component, dict) or component.get("id") is None:
        continue
    component_id = str(component["id"])
    if component_id in unneeded_ids:
        delete_response = requests.delete(
            f"{BASE_URL}/components/{component_id}"
        )
        delete_response.raise_for_status()

