import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.getenv("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response.json() if response.content else None


# Start a network-wide vulnerability scan.
scan = request("POST", "/scan/network", json={})

# Use scan findings to update the resource and scaling policy.
scan_id = scan.get("scan_id") or scan.get("id")
if scan_id:
    findings = request("GET", f"/scan/{scan_id}/results")
else:
    findings = request("GET", "/vulnerabilities")

resource_id = os.getenv("RESOURCE_ID")
repository_id = os.getenv("REPOSITORY_ID")

if not resource_id or not repository_id:
    raise ValueError("Set RESOURCE_ID and REPOSITORY_ID to the target resource and repository IDs.")

resource_updates = {
    "configuration": {
        "optimization_reason": "Address vulnerabilities and optimize performance based on scan findings",
        "scan_findings": findings,
    }
}
request("PATCH", f"/infrastructure/resources/{resource_id}", json=resource_updates)

scaling_policy = {
    "name": "vulnerability-response-autoscaling",
    "conditions": {
        "based_on": "network_scan_findings",
        "scan_findings": findings,
    },
    "actions": {
        "description": "Dynamically manage cloud resources in response to scan outcomes"
    },
}
request("POST", "/scaling/policies", json=scaling_policy)

request(
    "POST",
    f"/repositories/{repository_id}/branches",
    json={
        "name": "vulnerability-fixes",
        "description": "Track changes related to vulnerability fixes and resource updates",
    },
)

request(
    "POST",
    "/application/register",
    json={
        "name": "Vulnerability Resource Access Manager",
        "description": "Manage access control for identified vulnerabilities and resource updates",
    },
)

